from dataclasses import dataclass, field
from typing import Optional, Dict, Any

@dataclass
class KmsKey:
    key_id: str
    key_type: Optional[str] = None
    algorithm: Optional[str] = None

@dataclass
class EncryptRequest:
    plaintext: bytes
    key_id: str
    aad: Optional[bytes] = None

@dataclass
class EncryptResponse:
    ciphertext: bytes
    key_id: str
    aad: Optional[bytes] = None

@dataclass
class DecryptRequest:
    ciphertext: bytes
    key_id: str
    aad: Optional[bytes] = None

@dataclass
class DecryptResponse:
    plaintext: bytes
    key_id: str
    aad: Optional[bytes] = None

@dataclass
class SignRequest:
    message: bytes
    key_id: str

@dataclass
class SignResponse:
    signature: bytes
    key_id: str

@dataclass
class VerifyRequest:
    message: bytes
    signature: bytes
    key_id: str

@dataclass
class VerifyResponse:
    is_valid: bool
    key_id: str

@dataclass
class NormalizeResponse:
    data: Dict[str, Any]
    status_code: int = 200
    headers: Dict[str, str] = field(default_factory=dict)

from google.cloud import kms_v1

class SecurityClient:
    """
    Provides local configuration and client helper utilities for Key Management and Encryption.
    """

    def __init__(self, project_id: str, location: str, key_ring_id: str, key_id: str):
        self.project_id = project_id
        self.location = location
        self.key_ring_id = key_ring_id
        self.key_id = key_id
        self.kms_client = self._get_kms_client()

    def _get_kms_client(self):
        """
        Initializes and returns a Google Cloud KMS client.
        """
        return kms_v1.KeyManagementServiceClient()

    def get_key_name(self) -> str:
        """
        Constructs and returns the full KMS key name.
        """
        return self.kms_client.crypto_key_path(
            self.project_id, self.location, self.key_ring_id, self.key_id
        )
